package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	_ "github.com/mattn/go-sqlite3"
	"golang.org/x/crypto/bcrypt"
)

var (
	db       *sql.DB
	mu       sync.RWMutex
	sessions = make(map[string]string)
)

var uploadDir string

func init() {
	// Resolve to absolute path at startup to ensure prefix checks are reliable
	abs, err := filepath.Abs("uploads")
	if err != nil {
		log.Fatal(err)
	}
	uploadDir = abs
}

func generateSessionID() string {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		panic(err)
	}
	return hex.EncodeToString(b)
}

func authenticate(w http.ResponseWriter, r *http.Request) {
	username := r.FormValue("username")
	password := r.FormValue("password")

	var storedHash string
	err := db.QueryRow("SELECT password_hash FROM users WHERE username = ?", username).Scan(&storedHash)
	if err != nil {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	// Compare using bcrypt (constant-time, salted, adaptive-cost KDF)
	if err := bcrypt.CompareHashAndPassword([]byte(storedHash), []byte(password)); err != nil {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	sid := generateSessionID()
	mu.Lock()
	sessions[sid] = username
	mu.Unlock()

	http.SetCookie(w, &http.Cookie{
		Name:     "session",
		Value:    sid,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		Path:     "/",
	})
	fmt.Fprintf(w, "Authenticated")
}

func getUsername(r *http.Request) (string, bool) {
	cookie, err := r.Cookie("session")
	if err != nil {
		return "", false
	}
	mu.RLock()
	user, ok := sessions[cookie.Value]
	mu.RUnlock()
	return user, ok
}

func sanitizeFilename(name string) string {
	// Remove null bytes and control characters
	var clean strings.Builder
	for _, r := range name {
		if r > 31 && r != 127 && r != 0 {
			clean.WriteRune(r)
		}
	}
	return clean.String()
}

// validatePath ensures the resolved path stays within the upload directory
func validatePath(requestedPath string) (string, error) {
	// Sanitize the input
	cleaned := sanitizeFilename(requestedPath)

	// Join with base directory and resolve to absolute path
	joined := filepath.Join(uploadDir, cleaned)

	// Resolve to absolute to eliminate any remaining traversal
	absPath, err := filepath.Abs(joined)
	if err != nil {
		return "", fmt.Errorf("invalid path")
	}

	// Security check: ensure resolved absolute path starts with our upload directory
	if !strings.HasPrefix(absPath, uploadDir+string(filepath.Separator)) && absPath != uploadDir {
		return "", fmt.Errorf("path traversal detected")
	}

	return absPath, nil
}

func handleUpload(w http.ResponseWriter, r *http.Request) {
	user, ok := getUsername(r)
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, 10<<20) // 10MB limit

	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Create user subdirectory
	userDir := filepath.Join(uploadDir, user)
	if err := os.MkdirAll(userDir, 0750); err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	subPath := filepath.Join(user, header.Filename)
	destPath, err := validatePath(subPath)
	if err != nil {
		http.Error(w, "Invalid filename", http.StatusBadRequest)
		return
	}

	dst, err := os.Create(destPath)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer dst.Close()

	if _, err := io.Copy(dst, file); err != nil {
		http.Error(w, "Write error", http.StatusInternalServerError)
		return
	}

	log.Printf("User %s uploaded file to %s", user, destPath)
	fmt.Fprintf(w, "File uploaded successfully")
}

func handleDownload(w http.ResponseWriter, r *http.Request) {
	_, ok := getUsername(r)
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := r.URL.Query().Get("file")
	if filename == "" {
		http.Error(w, "Missing file parameter", http.StatusBadRequest)
		return
	}

	validPath, err := validatePath(filename)
	if err != nil {
		http.Error(w, "Invalid path", http.StatusBadRequest)
		return
	}

	info, err := os.Stat(validPath)
	if err != nil || info.IsDir() {
		http.Error(w, "File not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%q", filepath.Base(validPath)))
	w.Header().Set("Content-Type", "application/octet-stream")
	http.ServeFile(w, r, validPath)
}

func handleListFiles(w http.ResponseWriter, r *http.Request) {
	user, ok := getUsername(r)
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	userDir := filepath.Join(uploadDir, user)
	entries, err := os.ReadDir(userDir)
	if err != nil {
		fmt.Fprintf(w, "No files found")
		return
	}

	w.Header().Set("Content-Type", "text/plain")
	for _, entry := range entries {
		if !entry.IsDir() {
			fmt.Fprintf(w, "%s\n", entry.Name())
		}
	}
}

func logActivity(username, action, detail string) {
	_, err := db.Exec(
		"INSERT INTO activity_log (username, action, detail, timestamp) VALUES (?, ?, ?, ?)",
		username, action, detail, time.Now().Unix(),
	)
	if err != nil {
		log.Printf("Failed to log activity: %v", err)
	}
}

func main() {
	var err error
	db, err = sql.Open("sqlite3", "./app.db")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	_, err = db.Exec(`CREATE TABLE IF NOT EXISTS users (
		username TEXT PRIMARY KEY,
		password_hash TEXT NOT NULL
	)`)
	if err != nil {
		log.Fatal(err)
	}

	_, err = db.Exec(`CREATE TABLE IF NOT EXISTS activity_log (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		username TEXT,
		action TEXT,
		detail TEXT,
		timestamp INTEGER
	)`)
	if err != nil {
		log.Fatal(err)
	}

	if err := os.MkdirAll(uploadDir, 0750); err != nil {
		log.Fatal(err)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/login", authenticate)
	mux.HandleFunc("/upload", handleUpload)
	mux.HandleFunc("/download", handleDownload)
	mux.HandleFunc("/files", handleListFiles)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  15 * time.Second,
		WriteTimeout: 15 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	log.Printf("Starting server on %s", server.Addr)
	log.Fatal(server.ListenAndServeTLS("cert.pem", "key.pem"))
}
